  "createInclinicConsultation": {
    "bodyRequired": true,
    "body": {
      "type": "object",
      "required": [
        "provider_id",
        "appointment_date_time",
        "customers",
        "address"
      ],
      "properties": {
        "appointment_date_time": {
          "type": "string",
          "format": "date-time"
        },
        "service_mode": {
          "type": "string",
          "enum": [
            "at_provider_location"
          ]
        },
        "provider_id": {
          "type": [
            "integer",
            "string"
          ],
          "pattern": "^[+-]?[0-9]+$"
        },
        "customers": {
          "type": "array",
          "minItems": 1,
          "items": {
            "type": "object",
            "required": [
              "name",
              "api_customer_id",
              "mobile_number",
              "gender",
              "dob",
              "package_ids"
            ],
            "properties": {
              "name": {
                "type": "string",
                "pattern": "\\S"
              },
              "api_customer_id": {
                "type": "string",
                "pattern": "^[a-zA-Z0-9]+$"
              },
              "mobile_number": {
                "type": "string",
                "pattern": "^[0-9]{10}$"
              },
              "gender": {
                "type": "string",
                "enum": [
                  "male",
                  "female",
                  "non-binary"
                ]
              },
              "dob": {
                "type": "string",
                "format": "date"
              },
              "package_ids": {
                "type": "array",
                "items": {
                  "type": [
                    "integer",
                    "string"
                  ]
                }
              }
            }
          }
        },
        "address": {
          "allOf": [
            {
              "type": "object",
              "required": [
                "address_line_one",
                "address_line_two",
                "city",
                "state",
                "country",
                "latitude",
                "longitude"
              ],
              "properties": {
                "address_line_one": {
                  "type": "string",
                  "pattern": "\\S",
                  "maxLength": 254
                },
                "address_line_two": {
                  "type": "string",
                  "pattern": "\\S",
                  "maxLength": 254
                },
                "city": {
                  "type": "string",
                  "pattern": "\\S"
                },
                "state": {
                  "type": "string",
                  "pattern": "\\S"
                },
                "country": {
                  "type": "string",
                  "pattern": "\\S"
                },
                "pincode": {
                  "type": [
                    "string",
                    "integer"
                  ],
                  "pattern": "^[1-9][0-9]{5}$",
                  "minimum": 100000,
                  "maximum": 999999
                },
                "latitude": {
                  "type": "number",
                  "minimum": 0
                },
                "longitude": {
                  "type": "number",
                  "minimum": 0
                }
              }
            },
            {
              "required": [
                "pincode"
              ]
            }
          ]
        },
        "plan_id": {
          "type": "string"
        },
        "customer_plan_id": {
          "type": "integer",
          "minimum": 0
        },
        "subscription_id": {
          "type": "string"
        }
      }
    },
    "rules": [
      {
        "rule": "unique_by",
        "description": "Each customer needs its own api_customer_id.",
        "fields": [
          "customers[].api_customer_id"
        ]
      },
      {
        "rule": "relative_date",
        "description": "Each customer's dob must be on or before the same date one year ago (members must be at least 1 year old).",
        "fields": [
          "customers[].dob"
        ],
        "targets": [
          "customers[].dob"
        ],
        "before": "today",
        "years": -1,
        "inclusive": true
      },
      {
        "rule": "relative_date",
        "description": "appointment_date_time must be later than now (a time without an offset is read as IST).",
        "fields": [
          "appointment_date_time"
        ],
        "targets": [
          "appointment_date_time"
        ],
        "after": "now",
        "defaultOffset": "+05:30"
      }
    ]
  },
